# ============================================================
#  FSRM disk quota - Remove
#  Enforces the service's disk space limit as a hard File Server
#  Resource Manager quota on its root folder, so nothing (uploads,
#  logs, saves written by the server itself) can exceed it.
#  The limit is the one set in TCAdmin: the service's Disk Space,
#  or the blueprint's default when the service has none.
#  Windows Server only. Anywhere else the script does nothing.
# ============================================================
$Mode = 'Remove'

if (-not [System.Runtime.InteropServices.RuntimeInformation]::IsOSPlatform([System.Runtime.InteropServices.OSPlatform]::Windows)) { return }

$windowsPowerShell = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
if (-not (Test-Path -LiteralPath $windowsPowerShell)) {
    Write-Host "ℹ️ Windows PowerShell is not available on this machine. The disk quota is not enforced."
    return
}

$root = $ThisService.RootDirectory
if ([string]::IsNullOrWhiteSpace($root)) {
    Write-Host "ℹ️ This service has no root folder. There is no disk quota to manage."
    return
}

# The same limit the file manager and FTP enforce on uploads.
$limit = $ThisService.DiskSpace
if ($null -eq $limit) {
    $blueprint = $ThisService.Blueprint
    if ($null -eq $blueprint) { $blueprint = $ThisGame }
    if ($null -eq $blueprint) { $blueprint = $ThisDockerBlueprint }
    if ($null -ne $blueprint) { $limit = $blueprint.DefaultDiskSpace }
}
if ($null -eq $limit) { $limit = 0 }

# Values reach the worker as single-quoted literals. PowerShell also treats the curly quotes as quotes.
function ConvertTo-Literal([string]$Value) { "'" + ($Value -replace "['\u2018\u2019\u201A\u201B]", '$0$0') + "'" }
$label = ("$($ThisService.Name) (service $($ThisService.ServiceId))" -replace "[\r\n]+", ' ')
$header = @(
    '$Mode = ' + (ConvertTo-Literal $Mode)
    '$RootDirectory = ' + (ConvertTo-Literal $root)
    '$Limit = [Int64]' + ([Int64]$limit)
    '$Label = ' + (ConvertTo-Literal $label)
    '$Marker = ' + (ConvertTo-Literal 'TCAdmin:')
) -join "`r`n"

$worker = @'
# Runs in Windows PowerShell 5.1, where the ServerManager and FileServerResourceManager modules load natively.
# Every result line is "LEVEL|base64(utf8 message)" so the caller can show any character the console would mangle.
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

function Say([string]$Level, [string]$Message) {
    [Console]::Out.WriteLine($Level + '|' + [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($Message)))
}

function Format-Size([double]$Bytes) {
    $units = 'B', 'KB', 'MB', 'GB', 'TB'
    $i = 0
    while ($Bytes -ge 1024 -and $i -lt $units.Count - 1) { $Bytes /= 1024; $i++ }
    return ('{0:0.##} {1}' -f $Bytes, $units[$i])
}

function Get-QuotaAt([string]$QuotaPath) {
    $wanted = $QuotaPath.TrimEnd('\')
    return Get-FsrmQuota | Where-Object { $_.Path.TrimEnd('\') -eq $wanted } | Select-Object -First 1
}

# A hosted service's root can be a junction into its host's folder; FSRM needs the real folder.
function Resolve-RealFolder([string]$Folder) {
    for ($i = 0; $i -lt 16; $i++) {
        $item = Get-Item -LiteralPath $Folder -Force
        if (-not $item.LinkType) { return $item.FullName.TrimEnd('\') }
        $target = "$(@($item.Target)[0])"
        foreach ($prefix in '\\?\', '\??\') { if ($target.StartsWith($prefix)) { $target = $target.Substring($prefix.Length) } }
        if (-not [IO.Path]::IsPathRooted($target)) { $target = Join-Path (Split-Path $item.FullName -Parent) $target }
        $Folder = $target
    }
    throw "The service folder '$Folder' is a chain of more than 16 links."
}

try {
    $os = Get-CimInstance -ClassName Win32_OperatingSystem
    if ($os.ProductType -eq 1) {
        Say 'SKIP' "File Server Resource Manager is only available on Windows Server ($($os.Caption)). The disk quota is not enforced on this machine."
        exit 0
    }

    Import-Module ServerManager
    $feature = Get-WindowsFeature -Name FS-Resource-Manager
    if (-not $feature) {
        Say 'SKIP' "File Server Resource Manager is not available on $($os.Caption). The disk quota is not enforced on this machine."
        exit 0
    }

    if (-not $feature.Installed) {
        if ($Mode -eq 'Remove') {
            Say 'OK' 'File Server Resource Manager is not installed, so there is no quota to remove.'
            exit 0
        }

        # Services created together would otherwise run two feature installs at once.
        $mutex = New-Object System.Threading.Mutex($false, 'Global\TCAdmin.FsrmFeatureInstall')
        try {
            try { [void]$mutex.WaitOne([TimeSpan]::FromMinutes(20)) } catch [System.Threading.AbandonedMutexException] { }
            if (-not (Get-WindowsFeature -Name FS-Resource-Manager).Installed) {
                Say 'INFO' 'Installing File Server Resource Manager. This can take a few minutes...'
                $install = Install-WindowsFeature -Name FS-Resource-Manager -IncludeManagementTools
                if (-not $install.Success) { throw "Installing File Server Resource Manager failed (exit code $($install.ExitCode))." }
                if ("$($install.RestartNeeded)" -eq 'Yes') {
                    Say 'WARN' 'File Server Resource Manager was installed but Windows needs a restart. The quota will be applied the next time this script runs after the restart.'
                    exit 0
                }
                Say 'OK' 'File Server Resource Manager was installed.'
            }
        } finally {
            $mutex.ReleaseMutex()
            $mutex.Dispose()
        }
    }

    $srm = Get-Service -Name SrmSvc
    if ($srm.Status -ne 'Running') {
        Set-Service -Name SrmSvc -StartupType Automatic
        Start-Service -Name SrmSvc
    }
    Import-Module FileServerResourceManager

    if ($Mode -eq 'Remove') {
        $paths = @($RootDirectory.TrimEnd('\'))
        if (Test-Path -LiteralPath $RootDirectory -PathType Container) { $paths += Resolve-RealFolder $RootDirectory }
        $removed = $false
        foreach ($p in ($paths | Select-Object -Unique)) {
            $existing = Get-QuotaAt $p
            if ($existing) {
                Remove-FsrmQuota -Path $existing.Path -Confirm:$false
                Say 'OK' "Removed the disk quota from $($existing.Path)."
                $removed = $true
            }
        }
        if (-not $removed) { Say 'OK' 'This service has no disk quota to remove.' }
        exit 0
    }

    if (-not (Test-Path -LiteralPath $RootDirectory -PathType Container)) {
        Say 'SKIP' "The service folder $RootDirectory does not exist yet. The disk quota will be applied when the folder exists."
        exit 0
    }
    $path = Resolve-RealFolder $RootDirectory
    $existing = Get-QuotaAt $path
    $ours = $existing -and "$($existing.Description)".StartsWith($Marker)

    if ($Limit -le 0) {
        if ($ours) {
            Remove-FsrmQuota -Path $existing.Path -Confirm:$false
            Say 'OK' 'This service has no disk space limit, so its disk quota was removed.'
        } elseif ($existing) {
            Say 'INFO' "This service has no disk space limit. The quota on $path was not created by TCAdmin and was left unchanged."
        } else {
            Say 'OK' 'This service has no disk space limit, so there is no quota to enforce.'
        }
        exit 0
    }

    $description = "$Marker $Label"
    if (-not $existing) {
        New-FsrmQuota -Path $path -Size ([UInt64]$Limit) -Description $description | Out-Null
        Say 'OK' "Created a hard disk quota of $(Format-Size $Limit) on $path."
        # FSRM measures the existing files in the background, so the usage it reports now is incomplete.
        Say 'INFO' 'File Server Resource Manager is measuring the folder''s current usage in the background.'
        exit 0
    } elseif ([UInt64]$existing.Size -ne [UInt64]$Limit -or $existing.SoftLimit -or $existing.Disabled -or $existing.Description -ne $description) {
        Set-FsrmQuota -Path $path -Size ([UInt64]$Limit) -SoftLimit:$false -Disabled:$false -Description $description | Out-Null
        Say 'OK' "Updated the hard disk quota on $path to $(Format-Size $Limit)."
    } else {
        Say 'OK' "The hard disk quota of $(Format-Size $Limit) is already enforced on $path."
    }

    $quota = Get-QuotaAt $path
    $percent = [Math]::Round(([double]$quota.Usage / [double]$quota.Size) * 100, 0)
    if ([UInt64]$quota.Usage -gt [UInt64]$quota.Size) {
        Say 'WARN' "The folder already uses $(Format-Size $quota.Usage), more than the $(Format-Size $quota.Size) quota. Writes will fail until files are deleted."
    } else {
        Say 'OK' "Disk usage: $(Format-Size $quota.Usage) of $(Format-Size $quota.Size) ($percent%)."
    }
    exit 0
} catch {
    Say 'ERR' $_.Exception.Message
    exit 1
}
'@

$workerFile = Join-Path ([System.IO.Path]::GetTempPath()) ("tcadmin-fsrm-" + [guid]::NewGuid().ToString('N') + ".ps1")
[System.IO.File]::WriteAllText($workerFile, $header + "`r`n" + $worker, [System.Text.UTF8Encoding]::new($true))

$icons = @{ OK = '✅'; INFO = 'ℹ️'; SKIP = 'ℹ️'; WARN = '⚠️'; ERR = '❌' }
try {
    & $windowsPowerShell -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $workerFile 2>&1 | ForEach-Object {
        $line = "$_"
        if ($line -match '^(OK|INFO|SKIP|WARN|ERR)\|([A-Za-z0-9+/=]*)$') {
            Write-Host ($icons[$Matches[1]] + ' ' + [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Matches[2])))
        } elseif ($line.Trim()) {
            Write-Host $line
        }
    }
    $exitCode = $LASTEXITCODE
} finally {
    Remove-Item -LiteralPath $workerFile -Force -ErrorAction SilentlyContinue
}

if ($exitCode -ne 0) {
    throw "The disk quota could not be removed (Windows PowerShell exit code $exitCode)."
}
